boxes={0:{'label':'red','obj':{'key'}},1:{'label':'green','obj':{'coin'}},2:{'label':'blue','obj':{'marble'}}}
def bylab(x): return next(i for i,b in boxes.items() if b['label']==x)
def byobj(x): return next(i for i,b in boxes.items() if x in b['obj'])
def swapcont(a,b): i,j=bylab(a),bylab(b); boxes[i]['obj'],boxes[j]['obj']=boxes[j]['obj'],boxes[i]['obj']
def move(o,target): i=byobj(o);j=target();boxes[i]['obj'].remove(o);boxes[j]['obj'].add(o)
def swaplab(a,b): i,j=bylab(a),bylab(b); boxes[i]['label'],boxes[j]['label']=boxes[j]['label'],boxes[i]['label']
ops=[lambda:swapcont('red','blue'),lambda:move('key',lambda:byobj('coin')),lambda:swaplab('red','green'),lambda:move('marble',lambda:bylab('green')),lambda:move('coin',lambda:byobj('key')),lambda:swapcont('red','blue')]
for n,o in enumerate(ops,1): o(); print(n,boxes)
print({x:boxes[byobj(x)]['label'] for x in ['key','coin','marble']})
PY"

